const ERRS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const err = (e) => ({ t: 'e', v: e })
const num = (v) => ({ t: 'n', v })
const bool = (v) => ({ t: 'b', v })
const text = (v) => ({ t: 's', v })

