    let l = pow()
    while (peekOp('*') || peekOp('/')) {
      const op = toks[p++].v
      l = { type: 'bin', op, l, r: pow() }
    }
    return l
  }
  function pow() {
    const l = unary()
    if (peekOp('^')) { p++; return { type: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (peekOp('-') || peekOp('+')) {
      const op = toks[p++].v
      return { type: 'un', op, e: unary() }
    }
    return primary()
  }
  function primary() {
    if (p >= toks.length) fail()
    const t = toks[p++]
    if (t.k === 'num') return { type: 'num', v: t.v }
    if (t.k === 'op') {
      if (t.v === '(') {
        const e = cmp()
        if (!peekOp(')')) fail()
        p++
        return e
      }
      fail()
    }
    if (peekOp('(')) {
      p++
      const args = []
      if (peekOp(')')) { p++ } else {
        for (;;) {
          args.push(cmp())
          if (peekOp(',')) { p++; continue }
          if (peekOp(')')) { p++; break }
          fail()
        }
      }
      return { type: 'call', name: t.v.toUpperCase(), args }
    }
    if (peekOp(':')) {
      p++
      if (p >= toks.length || toks[p].k !== 'word') fail()
      const t2 = toks[p++]
      if (peekOp('(')) fail()
      return { type: 'range', a: t.v, b: t2.v }
    }
