  return Number.isFinite(x) ? num(x) : err('#DIV/0!')
}
// number coercion: returns value of type n or e
function toNum(v) {
  if (v.t === 'n' || v.t === 'e') return v
  if (v.t === 'b') return num(v.v ? 1 : 0)
