      return a ? cellValue(a.col, a.row) : err('#REF!')
    }
    case 'range': return err('#ERR!')
    case 'un': {
      const v = toNum(evalNode(n.e))
      if (v.t === 'e') return v
      return n.op === '-' ? num(-v.v) : v
    }
