      const l = evalNode(n.l), r = evalNode(n.r)
      if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
        if (l.t === 'e') return l
        if (r.t === 'e') return r
        const d = compare(l, r)
        switch (n.op) {
          case '=': return bool(d === 0)
          case '<>': return bool(d !== 0)
          case '<': return bool(d < 0)
          case '<=': return bool(d <= 0)
          case '>': return bool(d > 0)
          default: return bool(d >= 0)
        }
      }
      const a = toNum(l), b = toNum(r)
      if (a.t === 'e') return a
      if (b.t === 'e') return b
      switch (n.op) {
        case '+': return fin(a.v + b.v)
        case '-': return fin(a.v - b.v)
        case '*': return fin(a.v * b.v)
        case '/': return b.v === 0 ? err('#DIV/0!') : fin(a.v / b.v)
        default: return fin(Math.pow(a.v, b.v))
      }
    }
    case 'call': return evalCall(n)
  }
  return err('#ERR!')
}

