  const f = n.name
  const args = n.args
  if (!['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF'].includes(f)) return err('#NAME?')
  if (f === 'IF') {
    if (args.length !== 3) return err('#ERR!')
    if (args[0].type === 'range') return err('#ERR!')
    const c = evalNode(args[0])
    if (c.t === 'e') return c
    let truth
    if (c.t === 'b') truth = c.v
    else if (c.t === 'n') truth = c.v !== 0
    else return err('#VALUE!')
    const br = args[truth ? 1 : 2]
    if (br.type === 'range') return err('#ERR!')
    return evalNode(br)
  }
  if (f === 'ABS') {
    if (args.length !== 1) return err('#ERR!')
    if (args[0].type === 'range') return err('#ERR!')
    const v = toNum(evalNode(args[0]))
    return v.t === 'e' ? v : fin(Math.abs(v.v))
  }
  if (args.length < 1) return err('#ERR!')
  const vals = []
  for (const a of args) vals.push(...argValues(a))
  for (const v of vals) if (v.t === 'e') return v
  if (f === 'COUNT') return num(vals.filter((v) => v.t === 'n').length)
  const nums = []
  for (const v of vals) {
    const x = toNum(v)
    if (x.t === 'e') return x
    nums.push(x.v)
  }
  switch (f) {
    case 'SUM': return fin(nums.reduce((a, b) => a + b, 0))
    case 'MIN': return fin(Math.min(...nums))
    case 'MAX': return fin(Math.max(...nums))
    default: return fin(nums.reduce((a, b) => a + b, 0) / nums.length)
  }
}

function show(v) {
  switch (v.t) {
    case 'n': return String(Number(v.v.toPrecision(10)))
    case 'b': return v.v ? 'TRUE' : 'FALSE'
    default: return v.v
  }
}

let out = ''
for (const c of sorted) out += `${nameOf(c.col, c.row)}=${show(cellValue(c.col, c.row))}\n`
process.stdout.write(out)
"}

