    while (p < toks.length && toks[p].k === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { type: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (peekOp('+') || peekOp('-')) {
      const op = toks[p++].v
      l = { type: 'bin', op, l, r: mul() }
    }
    return l
  }
  function mul() {
    let l = pow()
    while (peekOp('*') || peekOp('/')) {
      const op = toks[p++].v
      l = { type: 'bin', op, l, r: pow() }
    }
    return l
  }
  function pow() {
    const l = unary()
    if (peekOp('^')) { p++; return { type: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (peekOp('-') || peekOp('+')) {
      const op = toks[p++].v
      return { type: 'un', op, e: unary() }
    }
    return primary()
  }
  function primary() {
    if (p >= toks.length) fail()
    const t = toks[p++]
    if (t.k === 'num') return { type: 'num', v: t.v }
    if (t.k === 'op') {
      if (t.v === '(') {
        const e = cmp()
        if (!peekOp(')')) fail()
        p++
        return e
      }
      fail()
    }
    if (peekOp('(')) {
      p++
      const args = []
      if (peekOp(')')) { p++ } else {
        for (;;) {
          args.push(cmp())
          if (peekOp(',')) { p++; continue }
          if (peekOp(')')) { p++; break }
          fail()
        }
      }
      return { type: 'call', name: t.v.toUpperCase(), args }
    }
    if (peekOp(':')) {
      p++
      if (p >= toks.length || toks[p].k !== 'word') fail()
      const t2 = toks[p++]
      if (peekOp('(')) fail()
      return { type: 'range', a: t.v, b: t2.v }
    }
    const u = t.v.toUpperCase()
    if (u === 'TRUE') return { type: 'bool', v: true }
    if (u === 'FALSE') return { type: 'bool', v: false }
    return { type: 'ref', w: t.v }
  }
  try {
    const e = cmp()
    if (p < toks.length) return null
    return e
  } catch {
    return null
  }
}

function misplaced(n, direct = false) {
  switch (n.type) {
    case 'range': return !direct
    case 'bin': return misplaced(n.l) || misplaced(n.r)
    case 'un': return misplaced(n.e)
    case 'call': return n.args.some((a) => misplaced(a, true))
    default: return false
  }
}

function rangeCells(n) {
  const a = parseAddr(n.a), b = parseAddr(n.b)
  if (!a || !b) return null
  const out = []
  for (let c = Math.min(a.col, b.col); c <= Math.max(a.col, b.col); c++)
    for (let r = Math.min(a.row, b.row); r <= Math.max(a.row, b.row); r++) out.push([c, r])
  return out
}

function collectDeps(n, set) {
  switch (n.type) {
    case 'ref': { const a = parseAddr(n.w); if (a) set.add(keyOf(a.col, a.row)); break }
    case 'range': { const cs = rangeCells(n); if (cs) for (const [c, r] of cs) set.add(keyOf(c, r)); break }
    case 'bin': collectDeps(n.l, set); collectDeps(n.r, set); break
    case 'un': collectDeps(n.e, set); break
    case 'call': n.args.forEach((a) => collectDeps(a, set)); break
  }
}

// ---------- cells
for (const c of cells.values()) {
  const s = c.content
  if (s[0] === '=') {
    c.ast = parseFormula(s.slice(1))
    c.formula = true
    c.bad = !c.ast || misplaced(c.ast)
  }
}

const sorted = [...cells.values()].sort((x, y) => x.col - y.col || x.row - y.row)

if (mode === 'deps') {
  let out = ''
  for (const c of sorted) {
    out += nameOf(c.col, c.row) + ':'
    if (c.formula && c.ast) {
      const set = new Set()
      collectDeps(c.ast, set)
      for (const k of [...set].sort((a, b) => a - b)) out += ' ' + nameOf(Math.floor(k / 1000), k % 1000)
    }
    out += '\n'
  }
  process.stdout.write(out)
  process.exit(0)
}

// ---------- evaluation
const memo = new Map()
const active = new Set()

function literal(s) {
  if (s === '') return num(0)
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(s)) return num(Number(s))
  if (ERRS.includes(s)) return err(s)
  return text(s)
}

function cellValue(c, r) {
  const k = keyOf(c, r)
  const cell = cells.get(k)
  if (!cell) return num(0)
  if (memo.has(k)) return memo.get(k)
  if (active.has(k)) return err('#CYCLE!')
  let v
  if (!cell.formula) v = literal(cell.content)
  else if (cell.bad) v = err('#ERR!')
  else {
    active.add(k)
    v = evalNode(cell.ast)
    active.delete(k)
  }
  memo.set(k, v)
  return v
}

function fin(x) {
  return Number.isFinite(x) ? num(x) : err('#DIV/0!')
}
// number coercion: returns value of type n or e
function toNum(v) {
  if (v.t === 'n' || v.t === 'e') return v
  if (v.t === 'b') return num(v.v ? 1 : 0)
  return err('#VALUE!')
}

const rank = { n: 0, s: 1, b: 2 }
function cpCompare(a, b) {
  const x = Array.from(a), y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}
function compare(a, b) {
  if (a.t !== b.t) return rank[a.t] - rank[b.t]
  if (a.t === 'n') return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
  if (a.t === 's') return cpCompare(a.v, b.v)
  return Number(a.v) - Number(b.v)
}

function argValues(n) {
  if (n.type === 'range') {
    const cs = rangeCells(n)
    if (!cs) return [err('#REF!')]
    return cs.map(([c, r]) => cellValue(c, r))
  }
  return [evalNode(n)]
}

function evalNode(n) {
  switch (n.type) {
    case 'num': return num(n.v)
    case 'bool': return bool(n.v)
    case 'ref': {
      const a = parseAddr(n.w)
      return a ? cellValue(a.col, a.row) : err('#REF!')
    }
    case 'range': return err('#ERR!')
    case 'un': {
      const v = toNum(evalNode(n.e))
      if (v.t === 'e') return v
      return n.op === '-' ? num(-v.v) : v
    }
    case 'bin': {
      const l = evalNode(n.l), r = evalNode(n.r)
      if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
        if (l.t === 'e') return l
        if (r.t === 'e') return r
        const d = compare(l, r)
        switch (n.op) {
          case '=': return bool(d === 0)
          case '<>': return bool(d !== 0)
          case '<': return bool(d < 0)
          case '<=': return bool(d <= 0)
          case '>': return bool(d > 0)
          default: return bool(d >= 0)
        }
      }
      const a = toNum(l), b = toNum(r)
      if (a.t === 'e') return a
      if (b.t === 'e') return b
      switch (n.op) {
        case '+': return fin(a.v + b.v)
        case '-': return fin(a.v - b.v)
        case '*': return fin(a.v * b.v)
        case '/': return b.v === 0 ? err('#DIV/0!') : fin(a.v / b.v)
        default: return fin(Math.pow(a.v, b.v))
      }
    }
    case 'call': return evalCall(n)
  }
  return err('#ERR!')
}

function evalCall(n) {
  const f = n.name
  const args = n.args
  if (!['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF'].includes(f)) return err('#NAME?')
  if (f === 'IF') {
    if (args.length !== 3) return err('#ERR!')
    if (args[0].type === 'range') return err('#ERR!')
    const c = evalNode(args[0])
    if (c.t === 'e') return c
    let truth
    if (c.t === 'b') truth = c.v
    else if (c.t === 'n') truth = c.v !== 0
    else return err('#VALUE!')
    const br = args[truth ? 1 : 2]
    if (br.type === 'range') return err('#ERR!')
    return evalNode(br)
  }
  if (f === 'ABS') {
    if (args.length !== 1) return err('#ERR!')
    if (args[0].type === 'range') return err('#ERR!')
    const v = toNum(evalNode(args[0]))
    return v.t === 'e' ? v : fin(Math.abs(v.v))
  }
  if (args.length < 1) return err('#ERR!')
  const vals = []
  for (const a of args) vals.push(...argValues(a))
  for (const v of vals) if (v.t === 'e') return v
  if (f === 'COUNT') return num(vals.filter((v) => v.t === 'n').length)
  const nums = []
  for (const v of vals) {
    const x = toNum(v)
    if (x.t === 'e') return x
    nums.push(x.v)
  }
  switch (f) {
    case 'SUM': return fin(nums.reduce((a, b) => a + b, 0))
    case 'MIN': return fin(nums.reduce((a, b) => Math.min(a, b)))
    case 'MAX': return fin(nums.reduce((a, b) => Math.max(a, b)))
    default: return fin(nums.reduce((a, b) => a + b, 0) / nums.length)
  }
}

function show(v) {
  switch (v.t) {
    case 'n': return String(Number(v.v.toPrecision(10)))
    case 'b': return v.v ? 'TRUE' : 'FALSE'
    default: return v.v
  }
}

let out = ''
for (const c of sorted) out += `${nameOf(c.col, c.row)}=${show(cellValue(c.col, c.row))}\n`
process.stdout.write(out)
